import{_ as o,o as t,c as a,am as l}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"项目代码规范使用","description":"","frontmatter":{"title":"项目代码规范使用","excerpt":"摘要","date":"2025-11-11 19:49:43","updated":"2025-11-11 19:49:43"},"headers":[],"relativePath":"项目落地/项目代码规范使用.md","filePath":"项目落地/项目代码规范使用.md","lastUpdated":null}'),c={name:"项目落地/项目代码规范使用.md"};function r(i,e,d,n,s,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<p>这里实际上有一些工具使用，Java 方面，可以不限于Java 内容，后面再扩展，先只基于 Java 做一些记录</p><h3 id="代码质量" tabindex="-1">代码质量 <a class="header-anchor" href="#代码质量" aria-label="Permalink to &quot;代码质量&quot;">​</a></h3><h4 id="你们一般通过什么插件去规范代码" tabindex="-1">你们一般通过什么插件去规范代码 <a class="header-anchor" href="#你们一般通过什么插件去规范代码" aria-label="Permalink to &quot;你们一般通过什么插件去规范代码&quot;">​</a></h4><p>一般通过 SonarLint 或者 Alibaba Java Coding，然后如果有提示会自己修改一下，不过现在更多可能是通过 skills 去做代码审查，以及规则 claude.md 的时候就需要做好相关的要求。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20261115112314640.png" alt="image.png"></p><h4 id="有没有实际遇到什么问题-比如如何避免空指针-或者硬编码之类的。" tabindex="-1">有没有实际遇到什么问题，比如如何避免空指针，或者硬编码之类的。 <a class="header-anchor" href="#有没有实际遇到什么问题-比如如何避免空指针-或者硬编码之类的。" aria-label="Permalink to &quot;有没有实际遇到什么问题，比如如何避免空指针，或者硬编码之类的。&quot;">​</a></h4><p>我们一般使用公共类抽离魔法值，避免硬编码的现象。</p><p>空指针一般会通过 Objects.equals 判断是否相等，还有就是精度金额的比较一般使用 compares，使用 decBigmal 的时候要需要小数声明位数。</p><p>空指针自查</p><p><strong>空指针自查要点</strong>：</p><ul><li>外部输入、RPC/DB 查询结果、<code>Map.get</code>、自动拆箱、链式调用、<code>equals</code> 调用方；</li><li>方法契约是否明确“可能为 null”；</li><li>用 <code>Objects.requireNonNull</code> 做入口校验，用 <code>Optional</code> 表达“可能不存在”，用空集合代替 null 集合；</li><li>开启 IDEA 的 <code>Constant conditions &amp; exceptions</code>、<code>@Nullable/@NotNull</code> 检查，配合 SpotBugs/SonarLint。</li></ul><p>↑ 有更好理解再记录一下</p><hr><p>项目代码规范，可以看一下 阿里的 文件，或者平时注意一下，记录一下基本的注意事项</p><ul><li>1、减少代码中的硬编码内容</li><li>2、</li></ul><h4 id="常见的一些问题" tabindex="-1">常见的一些问题 <a class="header-anchor" href="#常见的一些问题" aria-label="Permalink to &quot;常见的一些问题&quot;">​</a></h4><ul><li><strong>空 catch 吞异常</strong>：<code>catch (Exception e) {}</code> 导致任务失败但日志无痕。至少记录上下文，或包装后抛出。</li><li><strong>忽略 <code>Future</code> 异常</strong>：<code>executor.submit(task)</code> 后不 <code>get()</code> 也不处理异常，任务炸了没人知道。用 <code>CompletableFuture.exceptionally/handle</code> 或统一异常处理器。</li><li><strong><code>InterruptedException</code> 未恢复中断</strong>：捕获后必须 <code>Thread.currentThread().interrupt()</code>。</li><li><strong>资源未关闭</strong>：<code>InputStream</code>、<code>Connection</code> 用 try-with-resources。</li><li><strong>SQL 拼接</strong>：<code>&quot;... where name=&#39;&quot; + name + &quot;&#39;&quot;</code> 既有注入风险也易出错，用参数绑定。</li><li><strong><code>Long</code> 用 <code> ==</code> 比较</strong>：包装类型缓存范围外比较引用，用 <code>equals</code> 或拆箱前判空。</li><li><strong><code>SimpleDateFormat</code> 共享实例</strong>：线程不安全，用 <code>DateTimeFormatter</code>。</li><li><strong>循环内字符串拼接</strong>：用 <code>StringBuilder</code>。</li><li><strong>JPA N+1</strong>：循环里触发懒加载，用 <code>JOIN FETCH</code> 或批量抓取</li></ul><hr>',18)])])}const g=o(c,[["render",r]]);export{h as __pageData,g as default};
